The edge list can be processed directly with a disjoint set. At first, every vertex is a separate component. Whenever an edge joins two different roots, the component count goes down by one.

The code also handles `V = 0`, where there are no vertices and the answer is zero.

```cpp
#include <vector>
using namespace std;

class Solution {
    vector<int> parent;
    vector<int> size;

    int find(int node) {
        if (parent[node] == node) {
            return node;
        }
        return parent[node] = find(parent[node]);
    }

    bool unite(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);

        if (rootA == rootB) {
            return false;
        }

        if (size[rootA] < size[rootB]) {
            swap(rootA, rootB);
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
        return true;
    }

public:
    int findNumberOfComponent(int V, vector<vector<int>> &edges) {
        parent.resize(V);
        size.assign(V, 1);

        for (int i = 0; i < V; i++) {
            parent[i] = i;
        }

        int components = V;
        for (const vector<int> &edge : edges) {
            if (unite(edge[0], edge[1])) {
                components--;
            }
        }

        return components;
    }
};
```

Time complexity: `O((V + E) * alpha(V))`, which is close to linear.
Space complexity: `O(V)` for the disjoint set arrays.

A small adjacency list keeps the graph easy to visit. Start a DFS from every vertex that has not been seen yet. Each new start means another connected group.

For example, with edges `[[0, 1], [1, 2], [3, 4]]`, DFS visits `0, 1, 2` first and then starts again at `3`, so the answer is `2`.

```python
class Solution:
    def findNumberOfComponent(self, V, edges):
        graph = [[] for _ in range(V)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        visited = [False] * V

        def dfs(node):
            visited[node] = True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    dfs(neighbor)

        components = 0
        for node in range(V):
            if not visited[node]:
                components += 1
                dfs(node)

        return components
```

Time complexity: `O(V + E)`.
Space complexity: `O(V + E)`, including the graph and recursion stack.

Here the edges are first placed in a boolean matrix. This makes checking whether two vertices have an edge very direct. An iterative DFS then marks each group.

This is mainly useful when the graph is small or when constant-time edge checks are convenient. The matrix uses more memory than an adjacency list.

```cpp
#include <vector>
using namespace std;

class Solution {
public:
    int findNumberOfComponent(int V, vector<vector<int>> &edges) {
        vector<vector<bool>> connected(V, vector<bool>(V, false));

        for (const vector<int> &edge : edges) {
            int u = edge[0];
            int v = edge[1];
            connected[u][v] = true;
            connected[v][u] = true;
        }

        vector<bool> visited(V, false);
        int components = 0;

        for (int start = 0; start < V; start++) {
            if (visited[start]) {
                continue;
            }

            components++;
            vector<int> stack = {start};
            visited[start] = true;

            while (!stack.empty()) {
                int node = stack.back();
                stack.pop_back();

                for (int neighbor = 0; neighbor < V; neighbor++) {
                    if (connected[node][neighbor] && !visited[neighbor]) {
                        visited[neighbor] = true;
                        stack.push_back(neighbor);
                    }
                }
            }
        }

        return components;
    }
};
```

Time complexity: `O(V^2 + E)`.
Space complexity: `O(V^2)` for the matrix and `O(V)` for traversal data.

Kept the graph storage out of this one. For each unvisited vertex, a stack holds the current component, and every popped vertex scans the edge list to find its neighbors. It is easy to follow, but repeated edge scans make it slower than an adjacency list.

Dry run: if the edges are `[[0, 1], [1, 2]]`, starting from `0` pushes `1`, then `1` pushes `2`. After that all three vertices are marked, so only one component is counted.

```python
class Solution:
    def findNumberOfComponent(self, V, edges):
        visited = [False] * V
        components = 0

        for start in range(V):
            if visited[start]:
                continue

            components += 1
            stack = [start]
            visited[start] = True

            while stack:
                node = stack.pop()
                for u, v in edges:
                    if u == node and not visited[v]:
                        visited[v] = True
                        stack.append(v)
                    elif v == node and not visited[u]:
                        visited[u] = True
                        stack.append(u)

        return components
```

Time complexity: `O(V * E)` in the worst case because the whole edge list can be scanned for many vertices.
Space complexity: `O(V)` for the visited array and stack. The input edge list is not changed.

This version uses a queue instead of recursion. Every vertex is added to the queue once, and the BFS marks all vertices reachable from its starting point.

A graph with `V = 4` and edges `[[0, 1], [2, 3]]` gives two BFS runs, one for each group. An isolated vertex also starts its own run.

```java
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

class Solution {
    public int findNumberOfComponent(int V, List<List<Integer>> edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < V; i++) {
            graph.add(new ArrayList<>());
        }

        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        boolean[] visited = new boolean[V];
        int components = 0;

        for (int start = 0; start < V; start++) {
            if (visited[start]) {
                continue;
            }

            components++;
            Queue<Integer> queue = new ArrayDeque<>();
            queue.offer(start);
            visited[start] = true;

            while (!queue.isEmpty()) {
                int node = queue.poll();
                for (int neighbor : graph.get(node)) {
                    if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        queue.offer(neighbor);
                    }
                }
            }
        }

        return components;
    }
}
```

Time complexity: `O(V + E)`.
Space complexity: `O(V + E)` for the adjacency list, queue, and visited array.

