package interview;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

class Solution {
    public int findNumberOfComponent(int V, List<List<Integer>> edges) {
        List<List<Integer>> adjList = generateAdjList(V, edges);
        boolean[] visited = new boolean[V];
        Deque<Integer> queue = new ArrayDeque<>();

        int connectedComp = 0;

        for(int i=0; i<V; i++) {
            if(!visited[i]) {
                connectedComp++;
                visited[i] = true;
                queue.offerLast(i);

                while(!queue.isEmpty()) {
                    Integer num = queue.pollFirst();

                    for(int adj : adjList.get(num)) {
                        if(!visited[adj]) {
                            visited[adj] = true;
                            queue.offerLast(adj);
                        }
                    }

                }
            }
        }

        return connectedComp;

    }

    private List<List<Integer>> generateAdjList(int v , List<List<Integer>> edges) {
        List<List<Integer>> list = new ArrayList<>(v);

        for(int i=0; i<v; i++) {
            list.add(i,  new ArrayList<>());
        }

        for(List<Integer> inner : edges) {
            list.get(inner.get(0)).add(inner.get(1));
            list.get(inner.get(1)).add(inner.get(0));
        }

        return list;
    }
}


